-- Viewmodel-recoil comparison variant of cw_anomaly_m4a1. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "zatvor" in anm_shots, 3.852 units, peak frame 0, home frame 5 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_m4a1"

SWEP.PrintName = "M4A1 (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "zatvor"
	SWEP.BoltShootOffset = Vector(0, 0, 3.852)
	SWEP.BoltBonePositionRecoverySpeed = 66
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_m4a1_vmrecoil", "vgui/killicons/tfa_anomaly_m4a1", Color(255, 255, 255))
end

